  const map = new Map(grids.map(item => [item.sourceId, item.grid]));
  const touched = new Set();
  for (const change of changes) {
    const { sourceId, rowIndex } = splitRecordKey(change.recordKey), grid = map.get(sourceId);
    if (!grid) continue;
