function need(value, message) { if (!value) throw haystackHostError(message, 409, "HAYSTACK_SETUP_CONFLICT"); }
export async function initializeHaystackMerchantWorkspace({ directory, connection, name = "Starforge Haystack workspaces", releaseStore } = {}) {
